"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def common(a, b):
    result = []
    i = 0
    while (i < len(a)):
        item = a[i]
        j = 0
        found_in_b = False
        while (j < len(b)):
            if (b[j] == item):
                found_in_b = True
                break
            j = (j + 1)
        if found_in_b:
            k = 0
            already_in_result = False
            while (k < len(result)):
                if (result[k] == item):
                    already_in_result = True
                    break
                k = (k + 1)
            if (not already_in_result):
                result.append(item)
        i = (i + 1)
    return result

firstlist = [5, 8, 6, 3, 6, 9, 7, 0, 2]

secondlist = [2, 4, 3, 1, 7, 9, 7, 3]

common_elements = common(firstlist, secondlist)

print(f'{firstlist}\n{secondlist} \nCommon Elements: {common_elements}')
